/**
 * Production configuration diagnostics.
 *
 * This module deliberately accepts an env-like record instead of reading
 * process.env so the same rules can run during a Vite build, on the server,
 * and in focused tests without ever exposing secret values to the browser.
 */
export type RuntimeConfigEnvironment = "development" | "production";
export type RuntimeConfigPhase = "build" | "runtime";
export type RuntimeConfigIssueSeverity = "warning" | "error";
export type RuntimeConfigIssueCode = "auth-disabled-in-production" | "missing-auth-secret" | "weak-auth-secret" | "missing-a2a-secret" | "weak-a2a-secret" | "invalid-auth-url" | "missing-database-url" | "local-database-in-production" | "missing-required-env";
export interface RuntimeConfigRequirements {
    /** Whether the app's default or custom auth layer is expected to run. */
    authEnabled?: boolean;
    /** Whether the app needs a persistent database outside local development. */
    databaseRequired?: boolean;
    /** Additional non-secret keys the app declares as required. */
    requiredEnv?: readonly string[];
}
export interface RuntimeConfigIssue {
    code: RuntimeConfigIssueCode;
    severity: RuntimeConfigIssueSeverity;
    title: string;
    message: string;
    envKeys: string[];
}
export interface RuntimeConfigReport {
    ok: boolean;
    status: "ok" | "warning" | "error";
    environment: RuntimeConfigEnvironment;
    phase: RuntimeConfigPhase;
    issues: RuntimeConfigIssue[];
    prompt: string;
}
export interface RuntimeConfigReportOptions {
    environment?: RuntimeConfigEnvironment;
    phase?: RuntimeConfigPhase;
    appName?: string;
}
/** Parse the truthy spellings accepted by typed runtime configuration flags. */
export declare function isTruthyRuntimeValue(value: string | boolean | undefined): boolean;
export declare function runtimeConfigRequirementsFromSearchParams(searchParams: URLSearchParams): RuntimeConfigRequirements;
export declare function buildRuntimeConfigPrompt(report: Pick<RuntimeConfigReport, "environment" | "phase" | "issues">, appName?: string): string;
export declare function getRuntimeConfigReport(env: Record<string, string | undefined>, requirements?: RuntimeConfigRequirements, options?: RuntimeConfigReportOptions): RuntimeConfigReport;
export declare function formatRuntimeConfigReport(report: RuntimeConfigReport): string;
export declare function parseRuntimeConfigReport(value: unknown): RuntimeConfigReport | null;
